rder:0;background:#eef2f7;width:36px;height:36px;border-radius:50%;font-size:23px;cursor:pointer}.nmo-grid-2,.nmo-grid-3{display:grid;gap:12px}.nmo-grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.nmo-grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.nmo-checks{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:12px 0}.nmo-checks label{margin:0;font-weight:600;display:flex;gap:6px;align-items:center}.nmo-checks input{width:auto}.drop-zone{display:flex;align-items:center;justify-content:center;min-height:100px;border:2px dashed #b8c5d8;border-radius:14px;background:#f8faff;text-align:center;color:#53627a;cursor:pointer;padding:12px}.drop-zone.dragover{border-color:#215dcc;background:#eef4ff}.drop-zone input{display:none}.drop-zone small{color:#8a96a8}.drop-zone.compact{min-height:52px}.nmo-section-list{display:grid;gap:14px}.nmo-section-card{background:#fff;border:1px solid #e2e8f1;border-radius:18px;box-shadow:0 8px 28px #1720330a;overflow:hidden}.nmo-section-card.dragging,.nmo-item.dragging{opacity:.45}.nmo-section-bar{display:grid;grid-template-columns:auto minmax(260px,1fr) auto auto;gap:12px;align-items:center;padding:16px 18px;background:linear-gradient(180deg,#fff,#fbfcff)}.drag-handle{cursor:grab;color:#9aa7b8;font-weight:900;letter-spacing:-3px;font-size:18px}.drag-handle.small{font-size:14px}.nmo-section-title{display:flex;align-items:center;gap:11px}.nmo-section-title h3{margin:0 0 5px;font-size:17px}.nmo-order{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#eaf1ff;color:#215dcc;font-weight:900}.nmo-section-status{font-size:12px;color:#53627a;display:flex;gap:6px;align-items:center}.status-dot{width:8px;height:8px;border-radius:50%;background:#b42318}.status-dot.on{background:#12b76a}.chip,.mini-state{display:inline-block;border-radius:999px;padding:3px 7px;background:#eef2f7;color:#526079;font-size:10px;font-weight:700}.mini-state.good{background:#ecfdf3;color:#067647}.mini-state.bad{background:#fef3f2;color:#b42318}.icon-btn{border:1px solid #dce3ed;background:#fff;width:34px;height:34px;border-radius:10px;cursor:pointer;font-size:17px;color:#365073}.icon-btn:hover{border-color:#8eacf0;background:#f3f7ff}.nmo-section-desc,.nmo-item-comment{padding:0 18px 12px;color:#667085;font-size:13px}.nmo-items{border-top:1px solid #edf0f5}.nmo-item{border-bottom:1px solid #edf0f5}.nmo-item:last-child{border-bottom:0}.nmo-item-row{display:grid;grid-template-columns:auto auto auto minmax(220px,1fr) auto auto;gap:10px;align-items:center;padding:12px 18px}.item-check{width:auto}.type-badge{font-size:10px;font-weight:800;text-transform:uppercase;background:#f0f4fb;color:#45607e;border-radius:8px;padding:5px 7px;white-space:nowrap}.type-3,.type-15,.type-21,.type-22{background:#fff4e8;color:#a24c05}.type-1,.type-12{background:#eaf4ff;color:#175cd3}.type-16,.type-17{background:#f2edff;color:#6938ef}.nmo-item-main strong{font-size:13px}.nmo-flags{display:flex;gap:4px;flex-wrap:wrap}.nmo-inline-editor{margin:0 18px 14px;background:#f9fbfe}.nmo-section-footer{padding:12px 18px;background:#fbfcfe}.copy-selected-form{display:flex;gap:7px;align-items:center;margin-left:auto}.copy-selected-form select{min-width:280px}.nmo-empty{padding:18px;color:#758197;text-align:center;background:#fafbfc}.nmo-empty.big{padding:36px;border:2px dashed #d9e0ea;border-radius:16px}.nmo-modal{position:fixed;z-index:2000;inset:0;display:grid;place-items:center;padding:24px}.nmo-modal[hidden]{display:none}.nmo-modal-backdrop{position:absolute;inset:0;background:#101828b8;backdrop-filter:blur(3px)}.nmo-modal-card{position:relative;background:#fff;width:min(900px,96vw);max-height:92vh;overflow:auto;border-radius:22px;padding:22px;box-shadow:0 30px 80px #0005}.nmo-modal-head{position:sticky;top:-22px;background:#fff;padding:12px 0 14px;z-index:2;border-bottom:1px solid #edf0f5}.nmo-modal-head h3{margin:4px 0}.nmo-modal-actions{justify-content:flex-end;margin-top:16px}.safe-note{font-size:12px;background:#fff8e7;border:1px solid #f4d58a;padding:10px;border-radius:10px;color:#7a4a00;margin-top:7px}.type-field{margin-top:10px}.upload-progress{height:5px;border-radius:999px;background:#e8edf4;overflow:hidden;margin:10px 0}.upload-progress i{display:block;width:0;height:100%;background:#215dcc;transition:width .1s}.nmo-toast{position:fixed;right:24px;bottom:24px;z-index:3000;min-width:260px;max-width:430px;padding:13px 16px;border-radius:12px;background:#067647;color:#fff;box-shadow:0 15px 45px #0003;font-weight:700;transform:translateY(20px);opacity:0;pointer-events:none;transition:.2s}.nmo-toast.show{transform:none;opacity:1}.nmo-toast.err{background:#b42318}.nmo-collapse[hidden]{display:none}.nmo-collapse{animation:nmoIn .15s ease-out}@keyframes nmoIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}@media(max-width:1000px){.nmo-tools,.nmo-grid-3{grid-template-columns:1fr}.nmo-section-bar{grid-template-columns:auto 1fr auto}.nmo-section-status{display:none}.nmo-item-row{grid-template-columns:auto auto auto 1fr auto}.nmo-flags{display:none}}@media(max-width:700px){.nmo-grid-2{grid-template-columns:1fr}.nmo-item-row{grid-template-columns:auto auto 1fr auto}.type-badge{display:none}.copy-selected-form{width:100%;margin-left:0}.copy-selected-form select{min-width:0;flex:1}.nmo-hero{padding:18px}.nmo-program-select{min-width:100%}}
</style>
<div class="nmo-shell">
  <div class="nmo-hero"><div><div class="nmo-eyebrow" style="color:#a9bddc">Администрирование обучения</div><h2>Конструктор НМО / ДПО</h2><p>Полный современный аналог <b>add_nmo.php</b>: структура, материалы, тестовые пакеты, тетради, анкеты и управление доступом.</p></div><div class="nmo-program-select"><label>Специальность / программа</label><select id="programSelector">@foreach($programs as $p)<option value="{{$p->id}}" @selected($program?->id==$p->id)>{{$p->title}}</option>@endforeach</select></div></div>
  <div id="nmoWorkspace">@include('admin.legacy._nmo-workspace',compact('program','sections','programs','instructors','surveys','practiceCycles','allSections','legacyTypes'))</div>
</div>
<div id="nmoToast" class="nmo-toast"></div>
<script>
(()=>{
 const workspace=document.getElementById('nmoWorkspace'),selector=document.getElementById('programSelector'),toast=document.getElementById('nmoToast');
 let dragged=null;
 const csrf=()=>document.querySelector('input[name="_token"]')?.value||'';
 const show=(text,error=false)=>{toast.textContent=text;toast.classList.toggle('err',error);toast.classList.add('show');clearTimeout(window.__nmoToast);window.__nmoToast=setTimeout(()=>toast.classList.remove('show'),3500)};
 const programId=()=>selector?.value||'';
 async function refresh(){const url=new URL(@json(route('admin.nmo.index')),location.origin);url.searchParams.set('program_id',programId());const r=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!r.ok)throw new Error('Не удалось обновить конструктор');workspace.innerHTML=await r.text();history.replaceState({},'',url.pathname+'?'+url.searchParams.toString());syncTypeFields();}
 selector?.addEventListener('change',async()=>{selector.disabled=true;try{await refresh()}catch(e){show(e.message,true)}finally{selector.disabled=false}});
 function xhrForm(form){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest(),bar=form.querySelector('.upload-progress'),fill=bar?.querySelector('i');x.open('POST',form.action);x.setRequestHeader('X-Requested-With','XMLHttpRequest');x.setRequestHeader('Accept','application/json');x.upload.onprogress=e=>{if(e.lengthComputable&&bar){bar.hidden=false;fill.style.width=Math.round(e.loaded/e.total*100)+'%'}};x.onload=()=>{if(bar)bar.hidden=true;let d={};try{d=JSON.parse(x.responseText)}catch{d={message:'Некорректный ответ сервера'}}if(x.status>=200&&x.status<300)resolve(d);else{const first=d.errors?Object.values(d.errors).flat()[0]:null;reject(new Error(first||d.message||'Ошибка сохранения'))}};x.onerror=()=>reject(new Error('Ошибка сети'));x.send(new FormData(form));});}
 document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-ajax="1"]');if(!form)return;e.preventDefault();if(form.dataset.confirm&&!confirm(form.dataset.confirm))return;if(form.classList.contains('copy-selected-form')){form.querySelectorAll('input[data-copy-id]').forEach(x=>x.remove());const card=form.closest('.nmo-section-card');const ids=[...card.querySelectorAll('.item-check:checked')].map(x=>x.value);if(!ids.length){show('Сначала отметьте элементы для копирования',true);return}ids.forEach(id=>{const i=document.createElement('input');i.type='hidden';i.name='ids[]';i.value=id;i.dataset.copyId='1';form.append(i)})}const b=form.querySelector('button[type="submit"]');if(b)b.disabled=true;try{const d=await xhrForm(form);show(d.message||'Сохранено');const modal=form.closest('.nmo-modal');if(modal)modal.hidden=true;await refresh()}catch(err){show(err.message,true)}finally{if(b)b.disabled=false}});
 document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle-panel]');if(toggle){const el=document.getElementById(toggle.dataset.togglePanel);if(el)el.hidden=!el.hidden;return}const add=e.target.closest('[data-open-add]');if(add){const modal=document.getElementById('addItemModal'),input=document.getElementById('addItemSectionId');if(modal&&input){input.value=add.dataset.openAdd;const title=add.closest('.nmo-section-card')?.querySelector('.nmo-section-title h3')?.textContent||'раздел';const h=document.getElementById('addItemSectionName');if(h)h.textContent='Добавление в «'+title+'»';modal.hidden=false;syncTypeFields()}return}if(e.target.closest('[data-close-modal]')){const m=e.target.closest('.nmo-modal');if(m)m.hidden=true;return}});
 function syncTypeFields(){const sel=document.getElementById('legacyTypeSelect');if(!sel)return;const val=sel.value;document.querySelectorAll('#addItemModal .type-field').forEach(el=>{el.hidden=!el.dataset.types.split(',').includes(val)})}
 document.addEventListener('change',e=>{if(e.target.id==='legacyTypeSelect')syncTypeFields()});syncTypeFields();
 document.addEventListener('dragover',e=>{const z=e.target.closest('.drop-zone');if(z){e.preventDefault();z.classList.add('dragover')}if(dragged){const container=e.target.closest('[data-sort-kind]');const candidate=e.target.closest('[draggable="true"]');if(container&&candidate&&candidate!==dragged&&candidate.parentElement===dragged.parentElement){e.preventDefault();const r=candidate.getBoundingClientRect();candidate.parentElement.insertBefore(dragged,e.clientY<r.top+r.height/2?candidate:candidate.nextSibling)}}});
 document.addEventListener('dragleave',e=>{e.target.closest('.drop-zone')?.classList.remove('dragover')});
 document.addEventListener('drop',e=>{const z=e.target.closest('.drop-zone');if(z){e.preventDefault();z.classList.remove('dragover');const input=z.querySelector('input[type=file]');if(input&&e.dataTransfer.files.length){input.files=e.dataTransfer.files;const span=z.querySelector('span');if(span)span.textContent=e.dataTransfer.files.length===1?e.dataTransfer.files[0].name:e.dataTransfer.files.length+' файлов'}}if(dragged){const parent=dragged.parentElement,kind=parent?.dataset.sortKind;if(kind)saveOrder(parent,kind);dragged.classList.remove('dragging');dragged=null}});
 document.addEventListener('dragstart',e=>{const el=e.target.closest('[draggable="true"]');if(!el)return;dragged=el;el.classList.add('dragging');e.dataTransfer.effectAllowed='move'});document.addEventListener('dragend',()=>{dragged?.classList.remove('dragging');dragged=null});
 async function saveOrder(container,kind){const ids=[...container.children].filter(x=>x.dataset.sortId).map(x=>Number(x.dataset.sortId));if(!ids.length)return;try{const r=await fetch(@json(route('admin.nmo.reorder')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf()},body:JSON.stringify({kind,ids})});const d=await r.json();if(!r.ok)throw new Error(d.message||'Ошибка сортировки');show('Порядок сохранён')}catch(e){show(e.message,true)}}
 document.addEventListener('input',e=>{if(e.target.id!=='nmoFilter')return;const q=e.target.value.trim().toLowerCase();document.querySelectorAll('.nmo-section-card').forEach(x=>x.hidden=q&&!x.dataset.search.includes(q))});
 document.addEventListener('change',e=>{if(e.target.matches('.drop-zone input[type=file]')){const z=e.target.closest('.drop-zone'),s=z?.querySelector('span');if(s&&e.target.files.length)s.textContent=e.target.files.length===1?e.target.files[0].name:e.target.files.length+' файлов'}});
})();
</script>
@endsection